"""One-shot. Applies this session's weather changes to honestygfymodel.

NOT A REPO FILE. Upload it to the repo root, run it, screenshot the
RESULT line, then delete it:

    python apply_weather.py
    rm apply_weather.py

SUPERSEDES the earlier apply_weather.py. Same six files plus
kbo_precompute.py, and it carries the three venue-lookup fixes the
first live run exposed (Kia Tigers vs KIA Tigers, the full-length
Japanese park names, and an unrecognised venue beating the fallback).

WHAT IT WRITES
  * app/engines/intl_weather.py  - weather_badges() shared by both
                                   boards, NPB_HOME_VENUE fallback
  * npb_precompute.py            - NPB wired to the forecast engine,
                                   plus the spaced-venue fix
  * app/views/KBO.py             - renders the weather badges
  * app/views/NPB.py             - renders them + the CC BY credit
  * kbo_precompute.py            - passes its league to venue_for_game
  * tests/test_intl_weather_parity.py  (new)
  * HANDOFF.md                   - rewritten after the audit

WHY A SCRIPT INSTEAD OF SIX PASTES
Six paste-into-the-web-editor operations is six chances to truncate a
40 KB file, and this repo has already lost a league to exactly that:
a hand-retyped patch turned line[ak] into line[al] and took the WNBA
slate off the site for days while every test still passed.

So nothing here was typed. Every payload was base64-encoded straight
from a verified file, each target carries the sha256 of the version it
was built FROM, and if your tree differs NOTHING is written and the
script names the file that drifted.

It re-hashes every file AFTER writing and greps the written bytes for
the claims it makes, printing PASS/FAIL per check.
"""
import base64
import hashlib
import os
import sys


def sha(path):
    with open(path, "rb") as fh:
        return hashlib.sha256(fh.read()).hexdigest()[:16]


def main():
    # ---- 1. PRE-FLIGHT. Nothing is written until every file checks out.
    drift = []
    for rel, before, _after, *_body in FILES:
        exists = os.path.exists(rel)
        if before is None and exists:
            drift.append(rel + " (expected new, already present)")
        elif before is not None and not exists:
            drift.append(rel + " (missing)")
        elif before is not None and sha(rel) != before:
            drift.append(rel + " (changed since this was built)")

    if drift:
        print("ABORT: working tree does not match. Nothing was written.")
        for d in drift:
            print("  drift:", d)
        print("RESULT: aborted, " + str(len(drift)) + " file(s) drifted")
        return 1

    # ---- 2. WRITE. Each file once, whole.
    for rel, _before, _after, *body in FILES:
        parent = os.path.dirname(rel)
        if parent:
            os.makedirs(parent, exist_ok=True)
        with open(rel, "wb") as fh:
            fh.write(base64.b64decode("".join(body)))

    # ---- 3. VERIFY WHAT IS ON DISK, not what this script believes.
    failures = []
    for rel, _before, after, *_body in FILES:
        ok = os.path.exists(rel) and sha(rel) == after
        print(("PASS  " if ok else "FAIL  ") + rel)
        if not ok:
            failures.append(rel)

    # ---- 4. The claims, checked against the written bytes.
    grep = [
        ("engine exposes the shared renderer",
         "app/engines/intl_weather.py", "def weather_badges(", True),
        ("engine knows all 12 NPB home parks",
         "app/engines/intl_weather.py", "NPB_HOME_VENUE = {", True),
        ("club lookup is case-insensitive",
         "app/engines/intl_weather.py", "_HOME_BY_KEY.get(home.lower()", True),
        ("a scraped venue must resolve or fall back",
         "app/engines/intl_weather.py", "if league and not coords_for(league, s):", True),
        ("NPB pipeline forecasts its slate",
         "npb_precompute.py", "engines.intl_weather", True),
        ("NPB venue lookup ignores inner whitespace",
         "npb_precompute.py", 'key = re.sub(r"\\s+", "", jp or "")', True),
        ("NPB venue lookup handles full park names",
         "npb_precompute.py", "for k in sorted(STADIUMS, key=len, reverse=True):", True),
        ("both pipelines pass their league",
         "npb_precompute.py", '_venue_for(g.get("stadium"), g.get("home"), "npb")', True),
        ("KBO actually SHIPS the forecast",
         "kbo_precompute.py", '"temp_c": g.get("temp_c")', True),
        ("NPB actually SHIPS the forecast",
         "npb_precompute.py", '"temp_c": g.get("temp_c")', True),
        ("both ship heat_risk",
         "kbo_precompute.py", '"heat_risk": bool(g.get("heat_risk"))', True),
        ("KBO board renders weather",
         "app/views/KBO.py", "_weather_badges(g,", True),
        ("NPB board renders weather",
         "app/views/NPB.py", "_weather_badges(g,", True),
        ("NPB board carries the CC BY credit",
         "app/views/NPB.py", "_WX_ATTRIBUTION}</div>", True),
        ("no view hardcodes a threshold",
         "app/views/NPB.py", "RAIN RISK", False),
    ]
    for label, rel, needle, want in grep:
        try:
            text = open(rel, encoding="utf-8").read()
        except OSError:
            ok = False
        else:
            ok = (needle in text) if want else (needle not in text)
        print(("PASS  " if ok else "FAIL  ") + label)
        if not ok:
            failures.append(label)

    print("RESULT:", "all checks passed" if not failures
          else "FAILED " + "; ".join(failures))
    return 1 if failures else 0


